// State transition: placed order moves through valid order lifecycle states
// Generated by the QA spec generator (rung 2) — deterministic assembly; do not hand-edit.

import { test, expect } from '../../../fixtures';

test('TC-100: State transition: placed order moves through valid order lifecycle states', async ({ api, loginAs }) => {
  // reset_state is automatic (harness beforeEach)
  await loginAs('standard_user');
  const products: { id: number; name: string; description: string; price: number; stock: number; is_active: boolean }[] = await (await api.get('/api/products')).json();
  const inStock = products.filter((p) => p.stock >= 1).slice(0, 2);
  expect(inStock.length).toBe(2);
  const res = await api.post('/api/orders', { data: { items: inStock.map((p) => ({ product_id: p.id, quantity: 1 })) } });
  // Expected (full): Order created in initial pending state
  const orderId = (await res.json()).id;
  await api.patch(`/api/orders/${orderId}/status`, { data: { status: 'paid' } });
  // Expected: Valid transitions accepted and persisted
  await api.get(`/api/orders/${orderId}`);
  // Expected: Order state reflected correctly on each read
  // invalid transition: 'pending' is never a legal target state
  await api.patch(`/api/orders/${orderId}/status`, { data: { status: 'pending' } });
  // Expected: Invalid transition rejected without corrupting state
});
